int left = 0;
int longest = 0;

for (int right = 0; right < n; right++) {

  // Grow window until reaching a duplicated character
  freq[s[right]]++;

  // Shrink window until removing  duplicated character
  while (freq[s[right]] > 1) {
    freq[s[left++]]--;
  }

  // Update state
  int len = right - left + 1;
  if (len > longest) longest = len;
}
