unordered_map<char, int> lookup;

int left = 0;
int longest = 0;

for (int right = 0; right < n; right++) {
  // Last index of current character, or -1 as fallback value
  int last = lookup[s[right]] ?? -1;

  // Shrink window to remove duplicate characters
  if (last >= left) left = last + 1;

  // Update last index of current character
  lookup[s[right]] = right;

  // Update state
  int len = right - left + 1;
  if (len > longest) longest = len;
}
```

Comment: for small character sets, replace `unordered_map` with a frequency table array with entries initialized to `-1`.

