unordered_map<char, int> freq;

int distinct = 0;
int left = 0;
long count = 0;

for (int right = 0; right < n; right++) {
  if (++freq[arr[right]] == 1) distinct++;

  while (distinct > K) {
    if (--freq[arr[left++]] == 0) distinct--;
  }

  int len = right - left + 1;
  count += len;
}

return count;
```

Idiom: if `[left, right]` is a valid subarray of `arr`, there are `len = right - left + 1` valid subarrays of `[left, right]` ending at `right`.

